import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;
  const root = new ThreeGroup();
  const resources = [];
  const primitiveResults = [];
  let disposed = false;

  root.userData.handlers = {};

  const backdropGeometry = new ThreePlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    color('#0b0b10'),
    mix(color('#16161d'), color('#0b0b10'), smoothstep(0.35, 1.0, uv().y)),
    smoothstep(0.0, 1.0, uv().y)
  );
  backdropMaterial.toneMapped = false;

  const backdrop = new ThreeMesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const surfaceGeometry = new ThreePlaneGeometry(6.35, 1.7);
  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.88
  });
  surfaceMaterial.toneMapped = false;

  const surface = new ThreeMesh(surfaceGeometry, surfaceMaterial);
  surface.position.set(0, -0.05, -1.35);
  root.add(surface);
  resources.push(surfaceGeometry, surfaceMaterial);

  const imageGeometry = new ThreePlaneGeometry(6.1, 2.25);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.12,
    depthWrite: false
  });
  imageMaterial.toneMapped = false;

  const imagePlane = new ThreeMesh(imageGeometry, imageMaterial);
  imagePlane.position.set(0.25, -0.05, -1.1);
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const accentGeometry = new ThreePlaneGeometry(0.08, 1.15);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  accentMaterial.toneMapped = false;

  const accent = new ThreeMesh(accentGeometry, accentMaterial);
  accent.position.set(-3.0, 0, -0.92);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const ruleGeometry = new ThreePlaneGeometry(1.15, 0.018);
  const ruleMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  ruleMaterial.toneMapped = false;

  const rule = new ThreeMesh(ruleGeometry, ruleMaterial);
  rule.position.set(-2.45, -0.72, -0.9);
  root.add(rule);
  resources.push(ruleGeometry, ruleMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 42,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 1100,
      letterSpacingPx: 0
    });

    textObject.position.set(-2.72, 0.02, -0.72);
    root.add(textObject);
  }

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture?.dispose?.();
        return;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') continue;
    const result = ctx.primitives[primitive.name](root, primitive.params ?? {});
    if (result) primitiveResults.push(result);
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      if (object.userData?.cleanup && object.userData.cleanup !== root.userData.cleanup) {
        object.userData.cleanup();
      }
    });

    root.clear();
  };

  return root;
}
